<?php require_once __DIR__.'/../config/database.php'; require_once __DIR__.'/../config/header.php';
if($_SESSION['user']['role']!=='admin'){http_response_code(403);die('Access denied');}$msg='';
if($_SERVER['REQUEST_METHOD']==='POST'){$a=$_POST['action'];if($a==='add'){$s=$pdo->prepare('INSERT INTO restaurant_tables(table_no,seats) VALUES(?,?)');$s->execute([trim($_POST['table_no']),max(1,(int)$_POST['seats'])]);$msg='Table imeongezwa.';}elseif($a==='delete'){$s=$pdo->prepare('DELETE FROM restaurant_tables WHERE id=?');$s->execute([(int)$_POST['id']]);$msg='Table imefutwa.';}}
$tables=$pdo->query('SELECT * FROM restaurant_tables ORDER BY id')->fetchAll();?><h2>Table Management</h2><?php if($msg):?><div class="alert success"><?=e($msg)?></div><?php endif;?><div class="card"><form method="post" class="grid"><input type="hidden" name="action" value="add"><div><label>Table</label><input name="table_no" placeholder="Table 7" required></div><div><label>Seats</label><input type="number" name="seats" value="4" min="1"></div><div><label>&nbsp;</label><button class="green">+ Ongeza Table</button></div></form></div><br><div class="card"><table><tr><th>Table</th><th>Seats</th><th>Status</th><th>Action</th></tr><?php foreach($tables as $t):?><tr><td><?=e($t['table_no'])?></td><td><?=e($t['seats'])?></td><td><?=e($t['status'])?></td><td><form method="post" onsubmit="return confirm('Futa table?')"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$t['id']?>"><button class="btn red">Futa</button></form></td></tr><?php endforeach;?></table></div><?php require_once __DIR__.'/../config/footer.php';?>
